const args = process.argv.slice(2);
let sum = 0;
let valid = true;

for (const arg of args) {
    const num = Number(arg);
    if (isNaN(num)) {
        valid = false;
        break;
    }
    sum += num;
}

if (!valid) {
    process.exit(1);
} else {
    console.log(sum);
}

